import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './OrderPage.scss';
import { useLocation } from 'react-router-dom';

interface City {
    Ref: string;
    Description: string;
}

interface Warehouse {
    Ref: string;
    Description: string;
}

interface ApiResponse<T> {
    success: boolean;
    data: T;
    errors?: any[];
    warnings?: any[];
}

const OrderPage = () => {
    const location = useLocation<{ selectedDoctors: any[] }>();
    const selectedDoctors = location.state?.selectedDoctors || [];

    const [cities, setCities] = useState<City[]>([]);
    const [warehouses, setWarehouses] = useState<Warehouse[]>([]);
    const [selectedCity, setSelectedCity] = useState('');
    const [selectedWarehouse, setSelectedWarehouse] = useState('');
    const [formData, setFormData] = useState({
        name: '',
        email: '',
        address: '',
        phone: '',
    });

    const API_KEY = '4b43b81dfa23afae2dbf44851510a110'; // Вставте свій API-ключ

    // Завантаження списку міст
    useEffect(() => {
        axios
            .post<ApiResponse<City[]>>('https://api.novaposhta.ua/v2.0/json/', {
                apiKey: API_KEY,
                modelName: 'Address',
                calledMethod: 'getCities',
                methodProperties: {},
            })
            .then((response) => {
                if (response.data.success) {
                    setCities(response.data.data); // Перевірка на успішний запит
                } else {
                    console.error('Error fetching cities:', response.data.errors);
                }
            })
            .catch((error) => {
                console.error('Error fetching cities:', error);
            });
    }, []);

    // Завантаження відділень для обраного міста
    useEffect(() => {
        if (selectedCity) {
            axios
                .post<ApiResponse<Warehouse[]>>('https://api.novaposhta.ua/v2.0/json/', {
                    apiKey: API_KEY,
                    modelName: 'Address',
                    calledMethod: 'getWarehouses',
                    methodProperties: {
                        CityRef: selectedCity,
                    },
                })
                .then((response) => {
                    if (response.data.success) {
                        setWarehouses(response.data.data); // Перевірка на успішний запит
                    } else {
                        console.error('Error fetching warehouses:', response.data.errors);
                    }
                })
                .catch((error) => {
                    console.error('Error fetching warehouses:', error);
                });
        }
    }, [selectedCity]);

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const { name, value } = e.target;
        setFormData({ ...formData, [name]: value });
    };

    const validateForm = () => {
        const { name, email, phone } = formData;
        if (!name.trim()) {
            alert('Please enter your name.');
            return false;
        }
        if (!email.trim() || !/\S+@\S+\.\S+/.test(email)) {
            alert('Please enter a valid email address.');
            return false;
        }
        if (!phone.trim() || !/^\d{10}$/.test(phone)) {
            alert('Please enter a valid 10-digit phone number.');
            return false;
        }
        if (!selectedCity) {
            alert('Please select a city.');
            return false;
        }
        if (!selectedWarehouse) {
            alert('Please select a warehouse.');
            return false;
        }
        return true;
    };

    const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        if (validateForm()) {
            console.log('Form Data:', { ...formData, selectedCity, selectedWarehouse });
            alert('Order submitted successfully!');
            // Логіка для обробки замовлення
        }
    };

    return (
        <div className="order-page">
            <h1>Order Form</h1>

            {/* Відображення обраних лікарів */}
            <div className="selected-doctors">
                <h2>Selected Doctors</h2>
                <ul>
                    {selectedDoctors.map((doctor) => (
                        <li key={doctor.id}>
                            {doctor.doctor.name} - {doctor.doctor.specialty}
                        </li>
                    ))}
                </ul>
            </div>

            <form onSubmit={handleSubmit}>
                <div className="form-group">
                    <label htmlFor="name">Name</label>
                    <input
                        id="name"
                        name="name"
                        type="text"
                        value={formData.name}
                        onChange={handleInputChange}
                        placeholder="Ваня Степанюк"
                    />
                </div>
                <div className="form-group">
                    <label htmlFor="email">Email</label>
                    <input
                        id="email"
                        name="email"
                        type="email"
                        value={formData.email}
                        onChange={handleInputChange}
                        placeholder="stepan@gmail.com"
                    />
                </div>
                <div className="form-group">
                    <label htmlFor="phone">Phone</label>
                    <input
                        id="phone"
                        name="phone"
                        type="text"
                        value={formData.phone}
                        onChange={handleInputChange}
                        placeholder="Enter your phone number"
                        maxLength={10}
                    />
                </div>

                {/* Вибір міста */}
                <div className="form-group">
                    <label htmlFor="city">Місто</label>
                    <select
                        id="city"
                        value={selectedCity}
                        onChange={(e) => setSelectedCity(e.target.value)}
                    >
                        <option value="">Select your city</option>
                        {cities.map((city) => (
                            <option key={city.Ref} value={city.Ref}>
                                {city.Description}
                            </option>
                        ))}
                    </select>
                </div>

                {/* Вибір відділення */}
                <div className="form-group">
                    <label htmlFor="warehouse">Відділення</label>
                    <select
                        id="warehouse"
                        value={selectedWarehouse}
                        onChange={(e) => setSelectedWarehouse(e.target.value)}
                        disabled={!selectedCity}
                    >
                        <option value="">Select your warehouse</option>
                        {warehouses.map((warehouse) => (
                            <option key={warehouse.Ref} value={warehouse.Ref}>
                                {warehouse.Description}
                            </option>
                        ))}
                    </select>
                </div>

                <button type="submit">Submit Order</button>
            </form>
        </div>
    );
};

export default OrderPage;
